<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Simple Landing Page</title>
    <style>
        body {
            font-family: 'Arial', sans-serif;
            background-color: #f0f2f5;
            margin: 0;
            padding: 0;
            color: #333;
            line-height: 1.6;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
        }

        header {
            text-align: center;
            margin-bottom: 60px;
        }

        h1 {
            font-size: 3.5rem;
            margin-bottom: 10px;
            color: #4a4a4a;
            font-weight: 700;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.1);
        }

        .subtitle {
            font-size: 1.2rem;
            color: #666;
            max-width: 800px;
            margin: 0 auto;
        }

        .button-group {
            text-align: center;
            margin-top: 40px;
        }

        .btn {
            display: inline-block;
            padding: 16px 32px;
            margin: 0 10px;
            font-size: 1.1rem;
            font-weight: bold;
            text-decoration: none;
            border-radius: 50px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 4px 15px rgba(0,0,0,0.1);
            border: none;
            outline: none;
        }

        .btn-primary {
            background-color: #4a90e2;
            color: white;
        }

        .btn-secondary {
            background-color: #e24a4a;
            color: white;
        }

        .btn:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 25px rgba(0,0,0,0.15);
        }

        .btn:active {
            transform: translateY(-2px);
            box-shadow: 0 6px 15px rgba(0,0,0,0.1);
        }

        .btn-primary:hover {
            background-color: #3a7bc8;
        }

        .btn-secondary:hover {
            background-color: #c23a3a;
        }

        .btn-primary:active {
            background-color: #2c5a9c;
        }

        .btn-secondary:active {
            background-color: #a02c2c;
        }

        .fade-in {
            opacity: 0;
            animation: fadeIn 1.5s ease-in-out forwards;
        }

        @keyframes fadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        .glow {
            animation: glow 2s ease-in-out infinite alternate;
        }

        @keyframes glow {
            from { box-shadow: 0 0 5px rgba(0,0,0,0.2); }
            to { box-shadow: 0 0 20px rgba(0,0,0,0.4); }
        }

        footer {
            text-align: center;
            margin-top: 80px;
            padding: 20px;
            color: #777;
            font-size: 0.9rem;
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Welcome to Our Site</h1>
            <p class="subtitle">Discover amazing features and innovative solutions designed to make your life easier and more productive.</p>
        </header>

        <div class="button-group">
            <button class="btn btn-primary fade-in" id="btn1">Get Started</button>
            <button class="btn btn-secondary fade-in" id="btn2">Learn More</button>
        </div>

        <footer>
            &copy; 2023 Simple Landing Page. All rights reserved.
        </footer>
    </div>

    <script>
        // Add fade-in effect when page loads
        document.addEventListener('DOMContentLoaded', function() {
            const buttons = document.querySelectorAll('.btn');
            const fadeElements = document.querySelectorAll('.fade-in');

            // Fade in buttons after a small delay
            setTimeout(() => {
                fadeElements.forEach(el => {
                    el.classList.add('fade-in');
                });
            }, 300);

            // Add click animation to buttons
            buttons.forEach(btn => {
                btn.addEventListener('click', function(e) {
                    // Add glow effect on click
                    this.classList.add('glow');

                    // Remove glow after 500ms
                    setTimeout(() => {
                        this.classList.remove('glow');
                    }, 500);

                    // Add a small bounce effect on click
                    this.style.transform = 'translateY(-5px)';

                    setTimeout(() => {
                        this.style.transform = '';
                    }, 100);
                });
            });

            // Add hover effects to buttons
            buttons.forEach(btn => {
                btn.addEventListener('mouseenter', function() {
                    this.style.transform = 'translateY(-3px)';
                });

                btn.addEventListener('mouseleave', function() {
                    this.style.transform = '';
                });
            });
        });
    </script>
</body>
</html>
